(()=>{'use strict';
const D=window.TOEFL_DATA,C=window.CTEST_CATALOG,app=document.querySelector('#app');
const S=Object.fromEntries(D.stimuli.map(s=>[s.id,s])),Q=Object.fromEntries([...D.errors,...D.drills,...C,...window.TOEFL_TRANSFER].map(q=>[q.id,q]));
const courses={transfer:{title:'새 문제에 적용하기',description:'처음 보는 직접 제작 연습 '+window.TOEFL_TRANSFER.length+'문제 · 첫 풀이 별도 집계',ids:window.TOEFL_TRANSFER.map(q=>q.id)},original:{title:'내 오답 다시 풀기',description:'TPO2 → TPO3 → TPO4 순서로 원문 61문제',ids:D.errors.filter(q=>q.ready).map(q=>q.id)},ctest:{title:'C-Test 49개',description:'기존 빈칸 훈련 · 한 Task에 10개 단어',ids:C.map(q=>q.id)},correction:{title:'약점 교정 18문제',description:'반복한 판단 오류를 짧은 문제로 교정',ids:D.drills.map(q=>q.id)}};const orderedCourses={original:courses.original,ctest:courses.ctest,correction:courses.correction,transfer:courses.transfer};Object.keys(courses).forEach(k=>delete courses[k]);Object.assign(courses,orderedCourses);
let storageError='';const P=StudyProgress.create(localStorage,msg=>{storageError=msg;const el=document.querySelector('#storage-alert');el.textContent=msg;el.hidden=false;});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let page='home',id=null,draft={},courseFilter='original',stateFilter='all',bankTest='',bankSection='',search='';
const title=id=>S[Q[id]?.stimulus_id]?.title||Q[id]?.title||id;
const name=id=>id.startsWith('CTEST')?'Task '+Q[id].task:id;
const course=id=>StudyProgress.courseOf(id);
const info=id=>{const q=Q[id];return course(id)==='original'?`${q.test} · ${q.section==='Reading'?'읽기':'듣기'} · ${q.type}`:course(id)==='ctest'?'기존 C-Test · 빈칸 10개':course(id)==='transfer'?'직접 만든 신규 연습 · 텍스트 이해':'추가 교정 · 원문 성적과 별도';};
const statuses=id=>{const st=P.status(id),cl=st==='풀이 완료'?'good':st==='다시 확인'?'warn':st==='진행 중'?'active':'';return `<span class="badge ${cl}">${st}</span>`;};
const date=t=>t?new Date(t).toLocaleString('ko-KR',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'';
const finished=ids=>ids.filter(id=>P.latest(id)).length;
function nextFor(c){const ids=courses[c].ids,cursor=P.state.cursors[c];if(cursor&&ids.includes(cursor)&&(!P.latest(cursor)||P.state.drafts[cursor]&&!P.state.drafts[cursor].checked))return cursor;return ids.find(id=>P.state.drafts[id]&&!P.state.drafts[id].checked)||ids.find(id=>!P.latest(id))||ids.find(id=>P.needsReview(id)||P.due(id))||null;}
function recommendation(){const r=P.state.resume;if(r&&Q[r.id]&&courses[r.course]?.ids.includes(r.id)&&(!P.latest(r.id)||P.state.drafts[r.id]&&!P.state.drafts[r.id].checked))return r.id;if(r&&courses[r.course]&&nextFor(r.course))return nextFor(r.course);return Object.values(courses).flatMap(c=>c.ids).find(id=>P.due(id))||nextFor('original')||nextFor('ctest')||nextFor('correction')||nextFor('transfer');}
function homeBase(){const rec=recommendation(),all=Object.values(courses).flatMap(c=>c.ids),attempts=P.state.attempts,last=attempts.at(-1),weak=all.filter(id=>P.needsReview(id)),due=all.filter(id=>P.due(id));
return `<div class="eyebrow">내 학습</div><h1>오늘도 한 문제씩.</h1><p class="muted">풀다 멈춘 곳부터 이어가세요. 답과 풀이 기록은 자동 저장됩니다.</p>
<section class="card hero"><div class="eyebrow">${rec?(P.state.drafts[rec]&&!P.state.drafts[rec].checked?'입력하던 문제':'다음에 풀 문제'):'첫 풀이를 모두 마쳤어요'}</div><h1>${rec?esc(name(rec)+' · '+title(rec)):'학습 기록에서 다시 풀 문제를 골라보세요'}</h1><p class="muted">${rec?esc(info(rec)):finished(all)+' / '+all.length+'개 풀이 완료'}${last?'<br>마지막 풀이: '+esc(name(last.id))+' · '+date(last.time):''}</p><div class="row">${rec?`<button class="primary" data-open="${rec}">${P.state.drafts[rec]&&!P.state.drafts[rec].checked?'입력하던 곳 이어 풀기':attempts.length?'이어서 풀기 →':'첫 문제 풀기 →'}</button>`:''}<button class="secondary" data-page="courses">다른 문제 고르기</button></div></section>
<div class="summary-strip"><div><b>${finished(all)} <small class="muted">/ ${all.length}</small></b><span>한 번 이상 푼 문제·Task</span></div><div><b>${weak.length}</b><span>오답·힌트·헷갈린 문제</span></div><div><b>${due.length}</b><span>복습 날짜가 된 문제</span></div></div>
<h2 class="section-heading">내 훈련 코스</h2><div class="grid">${Object.entries(courses).map(([c,v])=>{const n=finished(v.ids),next=nextFor(c),w=v.ids.filter(id=>P.needsReview(id)).length;return `<section class="card course"><div class="eyebrow">${c==='original'?'01':c==='ctest'?'02':c==='correction'?'03':'04'}</div><h2>${v.title}</h2><p>${v.description}</p><div class="row between small"><span>첫 풀이 ${n} / ${v.ids.length}</span><span>${w?'다시 확인 '+w:''}</span></div><div class="progressbar"><i style="width:${100*n/v.ids.length}%"></i></div><p>${next?'다음: '+esc(name(next)):'모든 문제의 첫 풀이 완료'}</p><button data-course="${c}">${n?'진도 확인·이어 풀기':'코스 시작하기'}</button></section>`;}).join('')}</div>
${weak.length||due.length?`<div class="review-callout"><div><b>다시 확인하면 좋은 문제</b><p>틀렸거나 힌트가 필요했던 문제부터 모았습니다.</p></div><button data-review>복습할 문제 보기 (${new Set([...weak,...due]).size})</button></div>`:''}
<p class="small muted" style="margin-top:22px">원본과 연결된 오답 63개 중 자료가 갖춰진 61개를 채점합니다. 미확인 2개는 오답뱅크에서 확인할 수 있습니다. 듣기는 복원 스크립트·합성음성으로 연습합니다.</p>`;}
function row(id){const r=P.latest(id);return `<div class="list-item"><div><div class="list-title">${esc(name(id)+' · '+title(id))}</div><div class="meta">${statuses(id)}<span>${esc(info(id))}</span>${r?`<span>최근 ${r.score!==undefined?r.score+'/'+r.total:r.correct?'정답':'오답'} · ${date(r.time)}</span>`:''}${P.due(id)?'<span class="badge warn">복습 날짜 도착</span>':''}</div></div><button data-open="${id}">${P.status(id)==='진행 중'?'이어 풀기':r?'다시 풀기':'풀기'}</button></div>`;}
function coursesView(){const c=courses[courseFilter],ids=c.ids.filter(id=>stateFilter==='all'||stateFilter==='new'&&!P.latest(id)||stateFilter==='done'&&!!P.latest(id)||stateFilter==='progress'&&P.status(id)==='진행 중'||stateFilter==='review'&&(P.needsReview(id)||P.due(id)));const next=nextFor(courseFilter);
return `<h1>전체 문제와 진도</h1><p class="muted">‘풀이 완료’는 한 번 이상 채점했다는 뜻입니다. 헷갈린 문제는 ‘다시 확인’에 남습니다.</p><div class="row" style="margin-bottom:20px">${Object.entries(courses).map(([key,c])=>`<button data-course-filter="${key}" class="${key===courseFilter?'primary':''}">${c.title}</button>`).join('')}</div>
<section class="card"><div class="row between"><div><h2>${c.title}</h2><div class="small muted">첫 풀이 ${finished(c.ids)} / ${c.ids.length} · ${c.description}</div></div>${next?`<button class="primary" data-open="${next}">${P.state.drafts[next]?'이어 풀기':'다음 문제 풀기'} · ${esc(name(next))}</button>`:''}</div><div class="progressbar"><i style="width:${finished(c.ids)/c.ids.length*100}%"></i></div>
<label class="small">표시할 문제 <select id="status-filter"><option value="all">전체</option><option value="new">아직 안 푼 문제</option><option value="progress">진행 중</option><option value="review">다시 확인·복습</option><option value="done">한 번 이상 푼 문제</option></select></label><div class="list">${ids.length?ids.map(row).join(''):'<p class="empty">이 상태에 해당하는 문제가 없습니다.</p>'}</div></section>`;}
function review(){const ids=Object.values(courses).flatMap(c=>c.ids).filter(id=>P.needsReview(id)||P.due(id));return `<button class="back" data-page="home">← 내 학습</button><h1>다시 확인할 문제</h1><p class="muted">최근 풀이에서 틀렸거나 힌트·도움이 필요했던 문제, 복습 날짜가 된 문제입니다. 복습 간격은 1일 → 3일 → 7일 → 14일로 늘어납니다.</p><section class="card">${ids.length?ids.map(row).join(''):'<div class="empty">지금 다시 확인할 문제가 없습니다.<br><button data-page="home">다음 학습으로</button></div>'}</section>`;}
function source(q){return `<details class="source-details"><summary>최초 오답·원본 이미지·근거의 확실성</summary><p class="small">최초 내 답: ${esc(q.history.my_answer)}<br>원본에서 확인한 답: ${esc(q.observed_my_answer??'확인되지 않음')}<br>정답 출처: ${esc(q.answer_basis)}<br>원인 코드: ${esc(q.codes)} · ${esc(q.history.certainty)}<br>가능한 원인: ${esc(q.history.cause_original)}<br>미확인: ${esc(q.history.unknown)}</p><p class="small">보고서: <a href="${esc(q.report_file)}" target="_blank">${esc(q.history.source)}</a> · ${esc(q.date)}</p><a href="${esc(q.source_image)}" target="_blank" rel="noopener">원본 이미지 크게 보기 ↗</a><img src="${esc(q.source_image)}" class="sourceimg" loading="lazy" alt="${esc(q.id)} 원본 문제 이미지"></details>`;}
function optionView(q){return `<div class="options">${Object.entries(q.options).map(([letter,text])=>`<button class="option ${draft.selected===letter?'selected':''} ${draft.checked&&q.answer===letter?'correct':''} ${draft.checked&&draft.selected===letter&&q.answer!==letter?'wrong':''}" data-answer="${letter}" ${draft.checked?'disabled':''} aria-pressed="${draft.selected===letter}"><span class="letter">${letter}</span><span>${esc(text)}</span></button>`).join('')}</div>`;}
function ctestView(q){const target=q.prefix+'_'.repeat(q.missing_count),idx=q.blank_passage.indexOf(target);const field=`<span class="inline-word">${esc(q.prefix)}<input id="completion" class="completion" type="text" maxlength="${q.missing_count}" style="width:${q.missing_count+0.8}ch" value="${esc(draft.completion||'')}" aria-label="${esc(q.prefix)} 뒤에 빠진 ${q.missing_count}글자" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="${'_'.repeat(q.missing_count)}" ${draft.checked?'disabled':''}></span>`;
return `<p class="instruction">파란 빈칸을 눌러 빠진 <b>${q.missing_count}글자</b>를 입력하세요. 앞의 ‘${esc(q.prefix)}’는 이미 주어져 있습니다.</p><div class="passage ctest-passage">${esc(q.blank_passage.slice(0,idx))}${field}${esc(q.blank_passage.slice(idx+target.length))}</div><p class="small muted">문장 속에서 필요한 품사와 뜻을 생각하세요. 모르면 ‘모르겠어요’를 누를 수 있습니다.</p>`;}
function listeningStage(q,s){return `<div class="instruction"><b>1. 내용을 듣기</b> → 2. 답 고르기 → 3. 근거 확인하기</div><div class="audio-stage"><div class="audio-icon" aria-hidden="true">♪</div><h2>먼저 내용을 들어보세요</h2><p class="muted small">원본 음성파일이 없어 복원 스크립트를 합성음성으로 읽습니다.<br>실제 시험의 음성과는 다릅니다.</p><div class="row" style="justify-content:center"><button class="primary" id="speak">▶ 합성음성 듣기</button><button id="stop-speech">멈춤</button></div><p id="speech-status" class="small muted" aria-live="polite"></p></div><details id="transcript" ${draft.scriptOpen?'open':''}><summary>소리 대신 스크립트 읽기</summary><div class="passage">${esc(s.text)}</div></details><details><summary>기억한 내용 메모하기 (선택)</summary><textarea id="recall" placeholder="누가 / 무엇을 / 왜? 한국어로 적어도 됩니다.">${esc(draft.recall||'')}</textarea></details><div class="answerbar"><span class="small muted">내용을 듣거나 읽었다면 다음으로 이동하세요.</span><button class="primary" id="to-question">문제 풀기 →</button></div>`;}
function practiceBase(){const q=Q[id],c=course(id),s=S[q.stimulus_id],ids=courses[c].ids,n=ids.indexOf(id)+1,isListening=c==='original'&&q.section==='Listening',stage=draft.checked?3:isListening&&!draft.stage?1:2;
let body='';if(isListening&&stage===1)body=listeningStage(q,s);else{
 if(c==='transfer'){body=`<p class="instruction">${P.latest(q.id)?'전에 푼 추가 연습입니다. 이번 시도는 복습으로 기록합니다.':'처음 푸는 연습 문제입니다. 원문에서 익힌 원칙을 적용해 보세요.'}</p><h2 class="question">${esc(q.prompt)}</h2><div class="passage">${esc(q.passage)}</div>${optionView(q)}`;}
 else if(c==='correction'){const origin=Q[q.source_error_ids[0]],text=S[origin.stimulus_id].text;body=`<p class="instruction">기억한 내용을 바탕으로 답하세요. 헷갈리면 원문을 열어 근거를 찾으세요.</p><h2 class="question">${esc(q.prompt)}</h2><details><summary>원문 읽기 · 판단 근거 찾기</summary><div class="passage">${esc(text)}</div></details>${optionView(q)}`;}
 else if(q.kind==='ctest')body=ctestView(q);
 else if(q.kind==='insertion')body=`<p class="instruction">아래 문장을 넣을 자리를 지문의 A–D 버튼 중에서 고르세요.</p><div class="note">${esc(q.sentence)}</div><div class="passage">${esc(q.marked_passage).replace(/\[\[([ABCD])\]\]/g,(_,letter)=>`<button class="slot ${draft.selected===letter?'selected':''}" data-answer="${letter}" ${draft.checked?'disabled':''} aria-label="${letter} 위치에 문장 삽입">${letter}</button>`)}</div><p class="small">${draft.selected?'선택한 위치: '+draft.selected:'지문 안의 A, B, C, D 중 하나를 누르세요.'}</p>`;
 else body=`<p class="instruction">${isListening?'들은 내용에 맞는 답을 하나 고르세요.':'질문을 확인하고 지문에서 근거를 찾아 답을 하나 고르세요.'}</p><h2 class="question">${esc(q.question)}</h2>${isListening?`<div class="row"><button id="speak">▶ 다시 듣기</button><button id="stop-speech">멈춤</button></div><p id="speech-status" class="small muted" aria-live="polite"></p><details id="transcript" ${draft.scriptOpen?'open':''}><summary>스크립트로 근거 확인 (도움 기록)</summary><div class="passage">${esc(s.text)}</div></details>`:`<div class="passage">${esc(s.text)}</div>`}${optionView(q)}`;
 body+=draft.checked?feedback(q):`<div class="answerbar"><button class="back" id="unknown">모르겠어요 · 정답 보기</button><button class="primary" id="check">정답 확인하기</button></div><p id="answer-warning" class="error" role="status"></p>`;
 }
 return `<div class="work"><button class="back" data-page="home">← 저장하고 내 학습으로</button><div class="practice-head"><div class="row between"><span class="eyebrow">${courses[c].title}</span><span class="small muted">${n} / ${ids.length}</span></div><h1>${esc(title(id))}</h1><div class="small muted">${esc(id)} · ${esc(info(id))}</div></div><div class="steps"><span class="${stage===1?'active':''}">${stage===1?'<b>1. 내용 확인</b>':'1. 내용 확인'}</span><span>${stage===2?'<b>2. 답 입력</b>':'2. 답 입력'}</span><span>${stage===3?'<b>3. 근거 확인</b>':'3. 근거 확인'}</span></div><section class="card">${body}</section></div>`;}
function feedbackBase(q){const r=P.latest(id),c=course(id),next=P.next(courses[c].ids,id),correct=r.correct,key=q.options?`${q.answer}. ${q.options[q.answer]}`:q.answer;
return `<section class="result ${correct?'':'wrong'}" role="status"><h2>${correct?'맞혔어요. 근거도 확인하세요.':'이 부분을 확인하고 넘어가세요.'}</h2><p>내 답: <b>${esc(r.answer||'모르겠어요')}</b><br>정답: <b>${esc(key)}</b></p><p>${['correction','transfer'].includes(c)?esc(q.explanation):'<b>기록된 근거</b> · '+esc(q.evidence)}</p>${!correct?'<p class="small">이 문제는 ‘다시 확인’ 목록에 저장됐어요.</p>':''}${correct?`<label class="checkbox"><input id="uncertain" type="checkbox" ${r.uncertain?'checked':''}>맞혔지만 헷갈렸어요 · 다시 확인에 남기기</label>`:''}${r.hinted?'<p class="small muted">스크립트 도움을 받아 푼 문제로 기록했습니다.</p>':''}</section>${c==='original'?source(q)+(D.drills.some(d=>d.source_error_ids.includes(q.id))?'<div class="row" style="margin-top:16px"><span class="small muted">같은 약점 짧게 연습하기</span>'+D.drills.filter(d=>d.source_error_ids.includes(q.id)).map(d=>'<button class="linkbutton" data-open="'+d.id+'">'+esc(d.title)+' →</button>').join('')+'</div>':''):`<p class="small muted">연결된 원문: ${q.source_error_ids.map(e=>`<button class="linkbutton" data-open="${e}">${e}</button>`).join(' · ')}</p>`}<div class="answerbar"><button id="retry">같은 문제 다시 풀기</button><button class="primary" id="next">${next?'다음 문제 풀기 →':'코스 진도 확인 →'}</button></div>`;}
function reference(q){return `<button class="back" data-page="bank">← 오답뱅크</button><h1>${esc(q.id)} · 자료 확인이 필요해요</h1><div class="warning">${esc(q.note)}<br>미확인: ${esc(q.missing?.join(', '))}</div><p class="muted">정답을 추정해서 채점하지 않습니다. 복원된 원문과 출처는 아래에서 확인할 수 있습니다.</p><section class="card">${q.sentence?`<div class="note">${esc(q.sentence)}</div>`:''}<div class="passage">${esc(S[q.stimulus_id].text)}</div>${source(q)}</section>`;}
function bankBase(){const rows=D.errors.filter(q=>(!bankTest||q.test===bankTest)&&(!bankSection||q.section===bankSection)&&(!search||[q.id,title(q.id),q.question,q.history.prompt,q.history.my_answer,q.history.correct_answer,q.codes].join(' ').toLowerCase().includes(search.toLowerCase())));
return `<h1>내 오답뱅크</h1><p class="muted">최초 오답 63개 · TPO2 21개 / TPO3 최소 20개 / TPO4 22개<br>최초 답·정답·출처는 보존하고, 재풀이 결과는 별도로 쌓입니다.</p><div class="row" style="margin-bottom:18px"><select id="bank-test" aria-label="시험 회차"><option value="">모든 회차</option>${['TPO2','TPO3','TPO4'].map(t=>`<option ${bankTest===t?'selected':''}>${t}</option>`).join('')}</select><select id="bank-section" aria-label="영역"><option value="">모든 영역</option><option value="Reading" ${bankSection==='Reading'?'selected':''}>읽기</option><option value="Listening" ${bankSection==='Listening'?'selected':''}>듣기</option></select><input type="search" id="search" placeholder="문제·단어·오류 코드 검색" aria-label="오답 검색" value="${esc(search)}"><span class="small muted">${rows.length}개</span></div><section class="card">${rows.map(q=>`<div class="list-item"><div><div class="list-title">${esc(q.id+' · '+title(q.id))}</div><div class="small muted">${esc(q.type)} · ${esc(q.codes)} · ${q.ready?P.status(q.id):'자료 미확인'}</div><details><summary>최초 답과 정답·원인 보기</summary><p class="small">내 답: ${esc(q.history.my_answer)}<br>정답: ${esc(q.history.correct_answer)}<br>근거: ${esc(q.evidence)}<br>확실성: ${esc(q.history.certainty)}</p></details></div><button data-open="${q.id}">${q.ready?'재풀이':'자료 보기'}</button></div>`).join('')}</section><p class="small muted">TPO3 Listening 추가 단독 오답 6개는 전체 문제 수가 없어 시험 전체 정확도를 계산하지 않습니다.</p>`;}
function historyBase(){const all=Object.values(courses).flatMap(c=>c.ids),rows=P.state.attempts.slice().reverse();return `<h1>어디까지 풀었는지 한눈에</h1><p class="muted">코스별 진도와 최근 결과입니다. C-Test는 Task 단위로, 오답·교정은 문항 단위로 기록합니다.</p><div class="grid">${Object.entries(courses).map(([c,v])=>{const rs=P.state.attempts.filter(r=>r.course===c),next=nextFor(c);return `<section class="card"><h2>${v.title}</h2><h1>${finished(v.ids)} <small class="muted">/ ${v.ids.length}</small></h1><p class="small muted">풀이 시도 ${rs.length}회 · 다시 확인 ${v.ids.filter(id=>P.needsReview(id)).length}개</p><p class="small">${next?'다음: '+esc(name(next)+' · '+title(next)):'첫 풀이 모두 완료'}</p><button data-history-course="${c}">문제별 진도 보기</button></section>`;}).join('')}</div><section class="card" style="margin-top:20px"><h2>기록 백업·다른 기기로 옮기기</h2><p class="small muted">이 브라우저에 저장됩니다. 내려받은 백업을 다른 브라우저에서 가져오면 이어갈 수 있습니다. 기존 기록과 합쳐지며 같은 기록은 중복 저장하지 않습니다.</p><div class="row"><button id="export">기록 백업 내려받기</button><button id="import">백업 가져오기</button><input type="file" id="import-file" accept=".json,application/json" hidden></div><p id="import-message" class="small" role="status"></p></section><h2 class="section-heading">최근 풀이 기록 (${rows.length}회)</h2><p class="small muted">원문 재풀이·추가 교정·C-Test의 점수는 각각 별도로 표시합니다. 원래 시험 성적이나 새 문제 실력으로 환산하지 않습니다.</p><section class="card">${rows.length?`<div class="table-wrap"><table class="history-table"><thead><tr><th>문제·Task</th><th>결과</th><th>학습 방식</th><th>시간</th></tr></thead><tbody>${rows.slice(0,200).map(r=>`<tr><td><button class="linkbutton" data-open="${r.id}">${esc(name(r.id))}</button><br>${esc(title(r.id))}</td><td>${r.score!==undefined?r.score+' / '+r.total:r.correct?'정답':'오답'}${r.uncertain?' · 헷갈림':''}</td><td>${r.course==='ctest'?'C-Test':r.course==='correction'?'추가 교정':r.tts?'합성음성 재풀이':Q[r.id]?.section==='Listening'?'듣기 텍스트 재풀이':'읽기 원문 재풀이'}${r.hinted?' · 스크립트 도움':''}<br>${esc(r.recall||r.evidence||'')}</td><td>${date(r.time)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">아직 풀이 기록이 없습니다. 첫 문제를 풀면 여기에 자동 저장됩니다.</div>'}${rows.length>200?'<p class="small muted">최근 200회 표시 · 전체 기록은 백업에 포함됩니다.</p>':''}</section>`;}
function saveDraft(){tick();if(id&&page==='practice')P.draft(id,draft);}
function open(qid,fresh=false){if(!Q[qid])return;if(qid!==id&&'speechSynthesis'in window)speechSynthesis.cancel();if(course(qid)==='ctest'){if(fresh)P.draft(qid,{letters:[],checked:false});const url=new URL('../fillintheblank.html',location.href);url.searchParams.set('task',String(Q[qid].task));location.href=url.href;return;}id=qid;if(Q[id].ready===false){navigate('reference',false);return;}draft=fresh?{}:{...(P.state.drafts[id]||{})};if(fresh)P.draft(id,draft);P.touch(id);lastTick=null;navigate('practice',false);lastTick=performance.now();}
function navigate(p,clear=true){if(p!=='practice'&&'speechSynthesis'in window)speechSynthesis.cancel();if(clear)saveDraft();page=p;if(p!=='practice'&&p!=='reference')id=null;const hash=p==='practice'||p==='reference'?'#question/'+id:p==='analysis'?'#analysis/'+analysisId:p==='vocab'&&vocabId?'#vocab/'+vocabId:'#'+p;historyReplace(hash);render();window.scrollTo(0,0);app.focus({preventScroll:true});}
function historyReplace(hash){window.history.replaceState(null,'',hash);}
function render(){tick();document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===(['analysis','vocab','rules'].includes(page)?'bank':page)));app.innerHTML=({home,courses:coursesView,review,practice,reference:()=>reference(Q[id]),bank,history,analysis:analysisView,vocab:vocabView,rules:rulesView,growth}[page]||home)();bindBase();bindLearning();}
function check(unknown=false){const q=Q[id];let answer=q.kind==='ctest'?q.prefix+(draft.completion||'').trim().toLowerCase():draft.selected;
if(unknown)answer='';else if(!answer||(q.kind==='ctest'&&(draft.completion||'').length!==q.missing_count)){document.querySelector('#answer-warning').textContent=q.kind==='ctest'?'파란 빈칸을 모두 입력하거나 ‘모르겠어요’를 눌러주세요.':'보기를 하나 선택하거나 ‘모르겠어요’를 눌러주세요.';return;}
tick();lastTick=null;const base=course(id)==='transfer'?q.source_error_ids.map(qid=>P.state.analyses[qid]).find(a=>a?.status==='user_confirmed'&&a.ruleId===q.ruleId)||Object.values(P.state.analyses).find(a=>a.status==='user_confirmed'&&a.ruleId===q.ruleId):P.state.analyses[id];
P.add({id,difficulty:P.state.analyses[id]?.difficulty||null,confidence:draft.confidence??null,timeSpentMs:Math.round(draft.timeSpentMs||0),predictedPOS:draft.predictedPOS||null,posCorrect:draft.predictedPOS&&suggestionsFor(id).expectedPOS?draft.predictedPOS===suggestionsFor(id).expectedPOS:null,analysisSnapshot:base||null,reviewType:P.latest(id)?'repeat':course(id)==='transfer'?'new_transfer':'first_replay',kind:course(id)==='correction'?'derived':course(id)==='transfer'?'transfer':'original',answer,correct:answer===q.answer,hinted:!!draft.hinted,tts:!!draft.tts,recall:draft.recall||'',evidence:draft.evidence||''});draft.checked=true;draft.selected=answer;P.draft(id,draft);P.advance(courses[course(id)].ids,id);render();document.querySelector('.result')?.scrollIntoView({block:'nearest',behavior:'smooth'});}
function speak(){const s=S[Q[id].stimulus_id],status=document.querySelector('#speech-status');if(!('speechSynthesis'in window)){status.textContent='이 브라우저에서 소리를 재생할 수 없습니다. 스크립트를 읽고 진행하세요.';return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(s.speech_text||s.text);u.lang='en-US';u.rate=1;const voice=speechSynthesis.getVoices().find(v=>/^en[-_]/i.test(v.lang));if(voice)u.voice=voice;u.onstart=()=>{draft.tts=true;saveDraft();status.textContent='합성음성 재생 중 · 원본 음성 아님';};u.onend=()=>status.textContent='재생 완료 · 문제 풀기를 눌러 답을 골라보세요.';u.onerror=()=>status.textContent='소리를 재생할 수 없습니다. 아래 스크립트를 읽고 진행하세요.';speechSynthesis.speak(u);}
function bindBase(){const on=(selector,event,fn)=>document.querySelector(selector)?.addEventListener(event,fn);
app.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));app.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{saveDraft();const target=b.dataset.open;open(target,!!P.latest(target)&&!(P.state.drafts[target]&&!P.state.drafts[target].checked))});
app.querySelectorAll('[data-course],[data-course-filter],[data-history-course]').forEach(b=>b.onclick=()=>{courseFilter=b.dataset.course||b.dataset.courseFilter||b.dataset.historyCourse;stateFilter='all';navigate('courses')});
on('[data-review]','click',()=>navigate('review'));on('#status-filter','change',e=>{stateFilter=e.target.value;render()});if(document.querySelector('#status-filter'))document.querySelector('#status-filter').value=stateFilter;
app.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{draft.selected=b.dataset.answer;saveDraft();const scroll=window.scrollY;render();window.scrollTo(0,scroll)});
on('#completion','input',e=>{e.target.value=e.target.value.replace(/[^a-z]/gi,'').toLowerCase();draft.completion=e.target.value;saveDraft()});on('#completion','keydown',e=>{if(e.key==='Enter')check()});
on('#completion','paste',e=>{const q=Q[id],value=e.clipboardData.getData('text').trim().toLowerCase();if(value.startsWith(q.prefix)&&value.length===q.answer.length){e.preventDefault();e.target.value=value.slice(q.prefix.length);draft.completion=e.target.value;saveDraft();}});
on('#check','click',()=>check());on('#unknown','click',()=>check(true));on('#retry','click',()=>{P.draft(id,{});open(id,true)});
on('#next','click',()=>{const c=course(id),next=P.advance(courses[c].ids,id);if(next)open(next);else{courseFilter=c;stateFilter='all';navigate('courses',false)}});
on('#to-question','click',()=>{draft.stage=2;draft.scriptOpen=false;saveDraft();render();window.scrollTo(0,0)});on('#recall','input',e=>{draft.recall=e.target.value;saveDraft()});on('#speak','click',speak);on('#stop-speech','click',()=>{speechSynthesis.cancel();document.querySelector('#speech-status').textContent='재생을 멈췄습니다.'});on('#transcript','toggle',e=>{draft.scriptOpen=e.target.open;if(e.target.open)draft.hinted=true;saveDraft();});on('#uncertain','change',e=>P.uncertain(id,e.target.checked));
on('#bank-test','change',e=>{bankTest=e.target.value;render()});on('#bank-section','change',e=>{bankSection=e.target.value;render()});on('#search','input',e=>{search=e.target.value;const pos=e.target.selectionStart;render();const input=document.querySelector('#search');input.focus();input.setSelectionRange(pos,pos)});
on('#export','click',()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({...P.state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}));a.href=url;a.download='TOEFL-학습기록-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
on('#import','click',()=>document.querySelector('#import-file').click());on('#import-file','change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>15e6)throw Error('15MB 이하의 백업을 선택해주세요.');const n=P.merge(JSON.parse(await file.text()));render();document.querySelector('#import-message').textContent=`${n}개의 새 풀이 기록을 가져왔습니다. 중복 기록은 제외했습니다.`;}catch(err){document.querySelector('#import-message').textContent='가져오기 실패: '+err.message;}});
}
// The learning views share question IDs with the original bank and the C-Test page.
const B=window.TOEFL_DIAGNOSTICS,T=window.TOEFL_TRANSFER;
let analysisId=null,vocabId=null,bankTab='questions',growthTab='weakness',vocabSearch='',vocabMode='all',lastTick=null;
const posLabels={noun:'명사',verb:'동사',adjective:'형용사',adverb:'부사',participle:'분사구 (-ing 등)',gerund:'동명사'};
const codeLabel=code=>B.taxonomy.find(t=>t.code===code)?.label||'원인 확인 필요';
function spec(){const extra=Object.values(P.state.analyses).filter(a=>!B.rules.some(r=>r.id===a.ruleId)).map(a=>({id:a.ruleId,code:a.primary,title:codeLabel(a.primary),text:a.correctionRule}));return {...B,rules:[...B.rules,...extra.filter((r,i,a)=>a.findIndex(v=>v.id===r.id)===i)]};}
const metrics=()=>StudyAnalytics.build(P.state,spec(),Q);
function tick(force=false){if(lastTick!==null&&id&&page==='practice'&&!draft.checked&&(force||!document.hidden)){draft.timeSpentMs=(draft.timeSpentMs||0)+(performance.now()-lastTick);}lastTick=id&&page==='practice'&&!draft.checked&&!document.hidden?performance.now():null;}
const duration=ms=>ms==null?'미기록':Math.floor(ms/60000)+'분 '+Math.floor(ms%60000/1000)+'초';
function startAnalysis(qid){analysisId=qid;navigate('analysis');}
function bankNav(active){return `<div class="subnav"><button data-page="bank" class="${active==='questions'?'active':''}">문제별 오답</button><button data-page="rules" class="${active==='rules'?'active':''}">교정 규칙</button><button data-page="vocab" class="${active==='vocab'?'active':''}">연결된 어휘</button></div>`;}
function suggestionsFor(qid){return B.suggestions[qid]||{primary:qid.startsWith('CTEST')?'G9':Q[qid]?.targetCode||'',ruleId:qid.startsWith('CTEST')?'RULE-POS':Q[qid]?.ruleId||null,correctionRule:qid.startsWith('CTEST')?B.rules.find(r=>r.id==='RULE-POS').text:spec().rules.find(r=>r.id===Q[qid]?.ruleId)?.text||'',status:'inferred',secondary:[],evidence:Q[qid]?.explanation||'',vocabIds:[]};}
function linkedVocab(qid){return allVocab().filter(v=>v.questionIds?.includes(qid));}
function allVocab(){const merged=new Map();for(const v of [...B.vocab,...Object.values(P.state.customVocab)]){const key=v.term.toLowerCase().trim(),old=merged.get(key);if(old){old.questionIds=[...new Set([...(old.questionIds||[]),...(v.questionIds||[])])];old.sources=[...(old.sources||[]),...(v.sources||[])];old.aliasIds.push(v.id);}else merged.set(key,{...v,aliasIds:[v.id],questionIds:[...(v.questionIds||[])],sources:[...(v.sources||[])]});}return [...merged.values()].map(v=>{const edits=v.aliasIds.map(id=>P.state.vocabOverrides[id]).filter(Boolean).sort((a,b)=>Date.parse(a.updatedAt)-Date.parse(b.updatedAt));return {...v,...(edits.at(-1)||{})};});}
const wordReviews=wordId=>{const aliases=allVocab().find(v=>v.id===wordId||v.aliasIds.includes(wordId))?.aliasIds||[wordId];return P.state.vocabReviews.filter(r=>aliases.includes(r.id));};
const lastWord=id=>wordReviews(id).at(-1);
function analyseForm(qid){const seed=suggestionsFor(qid),saved=P.state.analyses[qid],a=draft.analysisForm&&id===qid?draft.analysisForm:saved||seed,r=P.latest(qid),baseline=r?.analysisSnapshot;
const fields=(key,fallback='')=>esc(a[key]??fallback),assessment=r?.assessment||{},canCompare=baseline?.status==='user_confirmed'&&StudyProgress.validCode(baseline?.primary);
return `<div class="analysis-panel"><div class="row between"><h2>왜 틀렸고, 다음에는 어떻게 풀까요?</h2><span class="badge ${saved?'good':'warn'}">${saved?.status==='user_confirmed'?'내가 확인한 진단':saved?.status==='user_unresolved'?'사용자 기록 · 원인 미확정':'원인·규칙 제안 · 아직 미확인'}</span></div><p class="small muted">원보고서 코드 ${esc(Q[qid]?.codes||'없음')}는 보존했습니다. 아래 세부 원인은 제안이므로 실제 생각과 맞는지 확인하세요.</p>
<form id="analysis-form" data-qid="${qid}"><div class="form-grid"><label>가장 큰 원인<select name="primary" id="primary-code"><option value="">실제 생각과 맞는 원인을 선택하세요</option><option value="unknown" ${a.primary==='unknown'?'selected':''}>아직 원인을 모르겠어요</option>${Object.entries(Object.groupBy?Object.groupBy(B.taxonomy,t=>t.group):B.taxonomy.reduce((o,t)=>{(o[t.group]??=[]).push(t);return o;},{})).map(([g,ts])=>`<optgroup label="${esc(ts[0].group_label)}">${ts.map(t=>`<option value="${t.code}" ${a.primary===t.code?'selected':''}>${t.code} · ${esc(t.label)}</option>`).join('')}</optgroup>`).join('')}</select></label><label>다음 문제에서 할 행동<textarea name="correctionRule" id="correction-rule" placeholder="예: 대상마다 특징을 적고 보기의 특징 주인을 확인한다. 원인을 아직 모르면 비워도 됩니다.">${fields('correctionRule')}</textarea></label></div>
<details><summary>내 생각·근거·추가 원인 자세히 남기기</summary><div class="form-grid"><label>당시 어떻게 해석했나요?<textarea name="whatIThought" placeholder="기록이 없으면 비워두세요.">${fields('whatIThought')}</textarea></label><label>왜 그 답을 골랐나요?<textarea name="whyIChose">${fields('whyIChose')}</textarea></label><label>놓친 근거 문장·구간<textarea name="evidenceSpan" placeholder="원문의 정확한 문장을 옮겨 적으세요.">${fields('evidenceSpan')}</textarea></label><label>내 답과 정답의 결정적 차이<textarea name="criticalDifference">${fields('criticalDifference')}</textarea></label><label>추가 원인 코드<input name="secondaryText" value="${esc((a.secondary||[]).join(', '))}" placeholder="예: V5, G9"></label><label>문제 체감 난이도<select name="difficulty"><option value="">미기록</option>${['쉬움','보통','어려움'].map(t=>`<option ${a.difficulty===t?'selected':''}>${t}</option>`).join('')}</select></label>${Q[qid]?.section==='Listening'?`<label>놓친 구간의 시각<input name="timestamp" placeholder="예: 00:35" value="${fields('timestamp')}"></label><label>실제로 들었다고 생각한 내용<textarea name="whatIHeard">${fields('whatIHeard')}</textarea></label><label>실제 스크립트와의 차이<textarea name="meaningGap">${fields('meaningGap')}</textarea></label><label>듣기에서 막힌 단계<select name="listeningFailure"><option value="">아직 모름</option>${['소리 인식','의미 이해','기억·연결','의도·추론','메모'].map(t=>`<option ${a.listeningFailure===t?'selected':''}>${t}</option>`).join('')}</select></label>`:''}</div></details><div class="row"><button type="submit">${saved?'진단·규칙 수정 저장':'내 원인·교정 규칙으로 저장'}</button><span class="small muted">저장하면 ‘사용자 확인’으로 기록됩니다.</span></div><p id="analysis-message" role="status" class="small"></p></form>
${r&&canCompare?`<div class="assessment"><h3>이번 풀이에서 같은 실수가 있었나요?</h3><p class="small muted">${canCompare?'이번 풀이를 시작하기 전에 저장해 둔 규칙과 비교합니다. 코드 '+esc(baseline?.primary)+' · '+esc(baseline?.correctionRule):'이 풀이 전에는 확인된 규칙이 없어 재발 여부를 집계하지 않습니다. 원인을 저장하면 다음 복습부터 비교할 수 있어요.'}</p><label>이번 결과<select id="assessment-outcome"><option value="unknown">아직 판단하기 어려워요</option>${!r.correct&&canCompare?'<option value="same">같은 원인으로 다시 틀렸어요</option>':''}${r.correct&&canCompare?'<option value="resolved">저장한 규칙을 적용해 근거를 찾았어요</option>':''}<option value="different">이번에는 다른 부분에서 막혔어요</option></select></label><label>판단한 근거<textarea id="assessment-evidence" placeholder="어떤 문장이나 구조를 확인했는지 한 줄">${esc(assessment.evidence||'')}</textarea></label><button id="save-assessment">이번 복습 결과 저장</button><p id="assessment-message" role="status" class="small">${assessment.outcome?'저장된 결과: '+esc({same:'같은 원인 재발',resolved:'규칙 적용 확인',different:'다른 원인',unknown:'확인 필요'}[assessment.outcome]):''}</p></div>`:r?'<p class="small muted">이 풀이 전에는 확인한 규칙이 없었습니다. 원인·규칙을 저장하면 다음 복습부터 비교합니다.</p>':''}
<div class="row related">${linkedVocab(qid).length?`<span class="small muted">관련 어휘</span>${linkedVocab(qid).map(v=>`<button class="linkbutton" data-word="${v.id}">${esc(v.term)}</button>`).join('')}`:'<span class="small muted">아래 어휘뱅크에서 단어를 추가하고 이 문제에 연결할 수 있습니다.</span>'}</div></div>`;}
function analysisView(){const q=Q[analysisId];if(!q)return '<p>문항을 찾지 못했습니다.</p>';const r=P.latest(analysisId);return `${bankNav('questions')}<button class="back" data-page="bank">← 문제별 오답</button><h1>${esc(name(analysisId)+' · '+title(analysisId))}</h1><div class="card"><p class="small">${q.history?'최초 내 답: '+esc(q.history.my_answer)+'<br>정답: '+esc(q.history.correct_answer):r?'최근 결과: '+(r.correct?'정답':'오답'):'아직 풀이 기록 없음'}</p>${q.history?`<p>기록된 근거: ${esc(q.evidence)}</p>`:''}${analyseForm(analysisId)}</div>${q.history?source(q):''}<details class="card"><summary>이 문항의 진단·규칙 변경 이력</summary>${P.state.analysisVersions.filter(a=>a.id===analysisId).slice().reverse().map(a=>`<p class="small">${date(a.time)} · ${esc(a.primary)} · ${esc(a.correctionRule)}<br>${esc(a.status==='user_confirmed'?'사용자 확인':'원인 미확정')}</p>`).join('')||'<p>아직 저장한 진단이 없습니다.</p>'}</details>`;}
function confidencePanel(){return `<div class="confidence-panel"><label>답에 얼마나 확신하나요? <select id="confidence"><option value="">선택 안 함</option>${[[5,'근거까지 확실'],[4,'대체로 확실'],[3,'두 답 사이에서 고민'],[2,'대략 추측'],[1,'거의 찍음']].map(([n,t])=>`<option value="${n}" ${Number(draft.confidence)===n?'selected':''}>${n} · ${t}</option>`).join('')}</select></label><span id="practice-time" class="small muted">풀이 시간 ${duration(draft.timeSpentMs||0)} · 화면을 떠난 시간 제외</span></div>`;}
function home(){const m=metrics(),rank=m.ruleStats.filter(r=>r.confirmedQuestions||r.same).sort((a,b)=>b.priority-a.priority),first=rank[0]||B.rules.find(r=>r.id==='RULE-ENTITY'),related=D.errors.filter(q=>suggestionsFor(q.id).ruleId===first.id);const q=related.find(q=>q.ready&&!P.latest(q.id))||related.find(q=>q.ready);const learning=`<h2 class="section-heading">실수를 줄이는 다음 단계</h2><div class="grid"><section class="card"><h2>1. 내 원인 확인</h2><p>확인한 원인 ${m.confirmedCount}개 · 제안 검토 ${m.unconfirmedCount}개</p><button data-analyze="${D.errors.find(q=>!P.state.analyses[q.id])?.id||D.errors[0].id}">오답 원인·규칙 확인</button></section><section class="card"><h2>2. 약점에 맞춰 연습</h2><p>${esc(first.title)}<br><span class="small">${rank.length?'확인된 진단·재발 기록 기준':'원보고서의 반복 패턴에 따른 제안'}</span></p>${q?`<button data-open="${q.id}">관련 원문 풀기</button>`:''}<button class="linkbutton" data-rule-train="${first.id}">새 문제에 적용 →</button></section><section class="card"><h2>3. 줄었는지 확인</h2><p>같은 원인 재발 ${m.same}회 · 규칙 적용 확인 ${m.resolved}회</p><button data-page="growth">변화와 근거 보기</button></section></div>`;return homeBase().replace('class="grid"','class="grid courses-grid"').replace('<h2 class="section-heading">내 훈련 코스',learning+'<h2 class="section-heading">내 훈련 코스');}
function practice(){let html=practiceBase();const q=Q[id];if(!draft.checked&&!(q.section==='Listening'&&!draft.stage))html=html.replace('<div class="answerbar">',confidencePanel()+'<div class="answerbar">');if(!draft.checked&&P.state.analyses[id]?.status==='user_confirmed')html=html.replace('<section class="card">','<section class="card"><div class="instruction"><b>이번에 적용할 규칙</b><br>'+esc(P.state.analyses[id].correctionRule)+'</div>');if(!draft.checked&&q.kind==='ctest')html=html.replace('<div class="passage ctest-passage">',`<label class="pos-prediction">단어를 쓰기 전에 필요한 품사를 예상해 보세요 <select id="predicted-pos"><option value="">아직 모르겠어요</option>${Object.entries(posLabels).map(([key,v])=>`<option value="${key}" ${draft.predictedPOS===key?'selected':''}>${v}</option>`).join('')}</select></label><div class="passage ctest-passage">`);return html;}
function feedback(q){const base=feedbackBase(q),r=P.latest(id),s=suggestionsFor(id);const panel=`${q.kind==='ctest'&&draft.predictedPOS?`<div class="warning">예상한 품사: ${esc(posLabels[draft.predictedPOS])} · 필요한 형태: ${esc(posLabels[s.expectedPOS]||'별도 확인')}<br>${r.posCorrect===false?'예상 품사와 필요한 형태가 다릅니다. 문장 자리를 다시 확인하세요.':'형태를 문장 구조와 함께 확인하세요.'}</div>`:''}<details ${!r.correct?'open':''}><summary>오답 원인·교정 규칙·이번 복습 결과 연결하기</summary>${analyseForm(id)}</details>${q.ruleId?`<p class="small muted">직접 만든 신규 연습입니다. 같은 문제의 두 번째 풀이부터는 신규 문제 성적에 포함하지 않습니다.</p>`:''}`;return base.replace('<div class="answerbar">',panel+'<div class="answerbar">');}
function bank(){return bankNav('questions')+bankBase().replace(/<button data-open="([^"]+)">/g,(_,qid)=>`<button class="linkbutton" data-analyze="${qid}">원인·규칙</button><button data-open="${qid}">`);}
function rulesView(){const m=metrics(),rules=spec().rules;return `${bankNav('rules')}<h1>다음 문제에서 바꿀 행동</h1><p class="muted">제안된 규칙은 문제별로 확인·수정할 수 있습니다. 실제로 확인한 원인과 복습 결과만 재발 통계에 들어갑니다.</p><div class="rule-grid">${rules.map(rule=>{const confirmed=Object.values(P.state.analyses).filter(a=>a.ruleId===rule.id),proposed=D.errors.filter(q=>suggestionsFor(q.id).ruleId===rule.id),stat=m.ruleStats.find(r=>r.id===rule.id);return `<section class="card"><span class="badge">${esc(rule.code)} · ${esc(codeLabel(rule.code))}</span><h2>${esc(rule.title)}</h2><p>${esc(rule.text)}</p><p class="small muted">내가 확인한 문항 ${confirmed.length}개 · 원문에서 재발 ${stat?.same||0}회 / 적용 확인 ${stat?.resolved||0}회</p><div class="row">${(confirmed.length?confirmed.map(a=>a.id):proposed.map(q=>q.id)).slice(0,6).map(qid=>`<button class="linkbutton" data-analyze="${qid}">${esc(name(qid))}${confirmed.length?'':' · 제안'}</button>`).join('')}</div><button data-rule-train="${rule.id}">${T.some(q=>q.ruleId===rule.id||q.targetCode===rule.code)?'이 원칙을 새 문제에 적용':'새 문제 목록 보기 · 이 원칙 문항 없음'}</button></section>`;}).join('')}</div>`;}
function vocabView(){if(vocabId)return wordView();const words=allVocab().filter(v=>(!vocabSearch||[v.term,v.meaning,v.issue].join(' ').toLowerCase().includes(vocabSearch.toLowerCase()))&&(vocabMode==='all'||vocabMode==='unknown'&&v.learnerStatus==='unknown'||vocabMode==='review'&&lastWord(v.id)?.result!=='known'&&!!lastWord(v.id)||vocabMode==='unconfirmed'&&v.learnerStatus==='unconfirmed'));
return `${bankNav('vocab')}<h1>오답에 연결된 어휘</h1><p class="muted">기존 65개는 학습 후보입니다. ‘몰랐던 단어’로 확정하지 않았습니다. C-Test에서 틀린 단어도 관련 Task와 연결됩니다.</p><div class="row"><input type="search" id="vocab-search" aria-label="어휘 검색" placeholder="단어·뜻·혼동 검색" value="${esc(vocabSearch)}"><select id="vocab-filter" aria-label="어휘 상태"><option value="all">전체</option><option value="unconfirmed">학습 상태 미확인</option><option value="unknown">뜻을 몰랐던 단어</option><option value="review">다시 확인할 어휘</option></select><button id="new-word">내 단어 추가</button></div><section class="card" style="margin-top:20px">${words.map(v=>{const r=lastWord(v.id);return `<div class="list-item"><div><div class="list-title">${esc(v.term)}</div><div class="small muted">${esc(v.meaning)} · 연결 문항 ${new Set(v.questionIds||[]).size}개<br>${r?'최근 자기평가: '+esc({known:'알았어요',uncertain:'헷갈림',unknown:'몰랐어요'}[r.result]):'아직 어휘 복습 없음'} · 발견 당시: ${v.learnerStatus==='unconfirmed'?'학습 상태 미확인':esc({known:'이미 알고 있음',unknown:'뜻을 몰랐음',misunderstood:'잘못 알고 있었음',context:'문맥 적용 실패',practice_error:'빈칸 복원 실패'}[v.learnerStatus]||v.learnerStatus)}</div></div><button data-word="${v.id}">뜻 회상하기</button></div>`;}).join('')||'<p class="empty">해당하는 어휘가 없습니다.</p>'}</section>`;}
let wordRevealed=false,wordAnswer='';
function wordView(){const v=allVocab().find(v=>v.id===vocabId||v.aliasIds.includes(vocabId));if(!v)return '<p>단어를 찾지 못했습니다.</p>';if(v.term==='새 단어')return newWordView(v);const r=lastWord(v.id);return `${bankNav('vocab')}<button class="back" id="word-list">← 어휘 목록</button><h1>${esc(v.term)}</h1><section class="card"><p class="instruction">문맥에서 무슨 뜻인지 떠올려 적은 뒤 ‘뜻 확인’을 누르세요.</p>${v.originalSentence?`<div class="passage">${esc(v.originalSentence)}</div>`:'<p class="small muted">해당 표현과 일치하는 원문 문장은 복원 자료에서 확인하지 못했습니다. 아래 연결 문제에서 문맥을 확인하세요.</p>'}<label>내가 떠올린 뜻<textarea id="word-answer" placeholder="한국어·영어 모두 가능">${esc(wordAnswer)}</textarea></label>${wordRevealed?`<div class="result"><h2>${esc(v.contextMeaning||v.meaning)}</h2><p>${esc(v.issue)}</p>${v.synonyms?'<p>문맥 동의어: '+esc(v.synonyms)+'</p>':''}<p class="small muted">직접 비교해 학습 결과를 선택하세요. 입력한 뜻을 자동으로 정답 판정하지 않습니다.</p><div class="row"><button data-word-result="known">알았어요</button><button data-word-result="uncertain">헷갈렸어요</button><button data-word-result="unknown">몰랐어요</button></div></div>`:'<button id="reveal-word" class="primary">뜻 확인</button>'}<p id="word-message" class="small" role="status">${r?'최근 복습: '+date(r.time)+' · 다음 확인: '+date(r.dueAt):''}</p><div class="related row">${(v.questionIds||[]).map(qid=>`<button class="linkbutton" data-analyze="${qid}">${esc(name(qid))} · 원인·규칙</button><button class="linkbutton" data-open="${qid}">문제 풀기</button>`).join('')}</div></section><details class="card"><summary>이 어휘의 복습 이력</summary>${wordReviews(v.id).slice().reverse().map(r=>`<p class="small">${date(r.time)} · ${esc({known:'알았어요',uncertain:'헷갈렸어요',unknown:'몰랐어요'}[r.result])} · 내 답: ${esc(r.answer||'미입력')}</p>`).join('')||'<p>아직 복습 기록이 없습니다.</p>'}</details><details class="card"><summary>뜻·혼동 표현·연결 문제 수정하기</summary><form id="word-edit"><div class="form-grid"><label>단어<input name="term" value="${esc(v.term)}" required></label><label>문맥의 뜻<input name="contextMeaning" value="${esc(v.contextMeaning||v.meaning)}" required></label><label>품사<input name="pos" value="${esc(v.pos||'')}"></label><label>혼동한 단어·표현<input name="confusedWith" value="${esc(v.confusedWith||'')}"></label><label>문맥 동의어<input name="synonyms" value="${esc(v.synonyms||'')}"></label><label>함께 쓰이는 표현<input name="collocations" value="${esc(v.collocations||'')}"></label><label>파생어<input name="wordFamily" value="${esc(v.wordFamily||'')}"></label><label>발견 당시 어휘 이해 상태<select name="learnerStatus">${[['unconfirmed','아직 확인 안 함'],['unknown','뜻을 몰랐음'],['misunderstood','잘못 알고 있었음'],['context','문맥에 적용하지 못함'],['known','이미 알고 있었음'],['practice_error','빈칸 복원 실패']].map(([key,label])=>`<option value="${key}" ${v.learnerStatus===key?'selected':''}>${label}</option>`).join('')}</select></label><label>연결 문항 ID (쉼표로 구분)<input name="questionIdsText" value="${esc((v.questionIds||[]).join(', '))}" placeholder="예: TPO4-R1, CTEST-01"></label><label>학습 우선순위<select name="priority">${['높음','중간','낮음','미평가'].map(t=>`<option ${v.priority===t?'selected':''}>${t}</option>`).join('')}</select></label></div><button type="submit">내용·연결 확인 저장</button><p id="word-edit-message" role="status"></p></form><p class="small muted">출처: ${(v.sources||[]).map(s=>esc(s.test+' · '+s.source)).join(' / ')}<br>원문 연결 ${v.linkStatus==='confirmed'?'사용자 확인':'제안 또는 복원 자료 기준'} · ${esc(v.certainty||v.issue)}</p></details>`;}
function newWordView(v){return `${bankNav('vocab')}<button class="back" id="word-list">← 어휘 목록</button><h1>내 단어 추가</h1><p class="muted">단어와 문맥의 뜻을 적고, 어느 문제에서 나왔는지 연결하세요.</p><section class="card"><form id="word-edit"><div class="form-grid"><label>단어<input name="term" required placeholder="예: residue"></label><label>문맥의 뜻<input name="contextMeaning" required placeholder="예: 과정 뒤 남은 잔여물"></label><label>혼동한 표현<input name="confusedWith" placeholder="예: resident"></label><label>연결할 문항 ID<input name="questionIdsText" placeholder="예: TPO4-R1, CTEST-01"></label><label>발견 당시 어휘 이해 상태<select name="learnerStatus"><option value="unconfirmed">아직 확인 안 함</option><option value="unknown">뜻을 몰랐음</option><option value="misunderstood">잘못 알고 있었음</option><option value="context">문맥 적용 실패</option></select></label></div><button class="primary">내용·연결 확인 저장</button><p id="word-edit-message" role="status"></p></form></section>`;}
function growth(){const m=metrics();let content='';if(growthTab==='tests')content=testView();else if(growthTab==='week')content=`<div class="card"><h2>최근 7일 학습 보고서</h2><div class="summary-strip"><div><b>${m.week.attempts}</b><span>풀이 시도</span></div><div><b>${m.week.unique}</b><span>서로 다른 문제·Task</span></div><div><b>${m.week.same} / ${m.week.resolved}</b><span>원문에서 재발 / 규칙 적용 확인</span></div></div><p class="small muted">확인한 규칙이 풀이 전에 저장되어 있고, 이번 원인을 직접 확인한 기록만 포함합니다.</p><h3>다음 훈련 우선순위</h3>${m.ruleStats.filter(r=>r.confirmedQuestions||r.same).sort((a,b)=>b.priority-a.priority).slice(0,3).map(r=>`<p><b>${esc(r.title)}</b> · 확인 문항 ${r.confirmedQuestions}개 / 재발 ${r.same}회 <button class="linkbutton" data-rule-train="${r.id}">연습하기 →</button></p>`).join('')||'<p>먼저 오답의 원인과 교정 규칙을 확인해주세요. 기록이 없는 개선 효과는 계산하지 않습니다.</p>'}</div>`;else if(growthTab==='plan')content=planView();else content=`<div class="summary-strip"><div><b>${m.confirmedCount}</b><span>직접 확인한 주원인 문항</span></div><div><b>${m.same} / ${m.same+m.resolved}</b><span>비교 가능한 원문 복습 중 같은 원인 재발</span></div><div><b>${m.transfer.correct} / ${m.transfer.total}</b><span>신규 문제 첫 풀이 정답 / 시도</span></div></div><section class="card"><h2>같은 실수가 줄었나요?</h2>${m.paired.length?`<p>같은 문항·같은 주원인을 두 번 이상 확인한 <b>${m.paired.length}문항</b>의 비교입니다.</p><div class="comparison"><div><b>${m.pairedBefore}%</b><span>처음 확인한 복습의 재발 비율</span></div><span>→</span><div><b>${m.pairedAfter}%</b><span>가장 최근 복습의 재발 비율</span></div></div><p>${m.pairedAfter<m.pairedBefore?'이 문항들에서는 같은 원인 재발 비율이 낮아졌습니다.':m.pairedAfter>m.pairedBefore?'이 문항들에서는 같은 원인 재발 비율이 높아졌습니다.':'이 문항들에서는 재발 비율의 변화가 없습니다.'} ${m.paired.length<3?'표본이 적어 전체 실력 개선으로 해석하기 어렵습니다.':''}</p>`:'<p>아직 비교할 기록이 부족합니다.</p><p class="small muted">원인·규칙을 먼저 저장하고, 복습 후 ‘같은 원인 재발 / 규칙 적용 확인’을 두 번 이상 남기면 같은 문항끼리 비교합니다.</p>'}<p class="small muted">C-Test 49개 Task의 별도 비교: 같은 원인 재발 ${m.ctest.same}회 / 적용 확인 ${m.ctest.resolved}회 (${m.ctest.total}회 확인).<br>단순 재풀이 정답 증가와 동일 원인 감소를 구분합니다. 재발 여부를 모르겠다고 남긴 기록은 분모에서 제외합니다.</p></section><div class="grid two"><section class="card"><h2>확인한 주원인</h2>${m.frequency.map(t=>`<div class="stat-line"><span>${esc(t.code+' · '+t.label)}</span><b>${t.count}문항</b></div>`).join('')||'<p class="muted">사용자가 확인한 원인이 아직 없습니다.</p>'}<p class="small muted">한 문항의 주원인은 한 번만 셉니다. 추정 원인·부원인은 이 빈도에 더하지 않습니다.</p></section><section class="card"><h2>새 문제 적용과 확신도</h2><p>새 문제 첫 풀이: <b>${m.transfer.correct} / ${m.transfer.total}</b>${m.transfer.rate!==null?' ('+m.transfer.rate+'%)':''}</p><p>문항형 훈련에서 확신도 4–5였던 풀이 중 오답: <b>${m.highConfidence.wrong} / ${m.highConfidence.total}</b></p><p class="small muted">새 문제는 직접 만든 연습입니다. 반복 시도와 힌트 사용 첫 풀이는 신규 성적에서 제외합니다. 공식 TOEFL 점수로 환산하지 않습니다.</p></section></div><section class="card"><h2>교정 규칙별 확인 결과</h2>${m.ruleStats.filter(r=>r.confirmedQuestions||r.same||r.transferTotal).map(r=>`<div class="list-item"><div><b>${esc(r.title)}</b><p class="small muted">확인 문항 ${r.confirmedQuestions}개 · 원문 재발 ${r.same}회 / 적용 확인 ${r.resolved}회 · 새 문제 첫 풀이 ${r.transferCorrect}/${r.transferTotal}</p></div><button data-rule-train="${r.id}">연습</button></div>`).join('')||'<p class="muted">원인 확인과 훈련 기록이 쌓이면 표시됩니다.</p>'}</section><details class="card"><summary>읽기·듣기 유형별 재풀이 결과</summary>${m.typeStats.map(s=>`<div class="stat-line"><span>${s.section==='Reading'?'읽기':'듣기'} · ${esc(s.type)}</span><b>${s.correct}/${s.total}</b></div>`).join('')||'<p>아직 재풀이 기록이 없습니다.</p>'}<h3>체감 난이도별 재풀이</h3>${m.difficultyStats.map(s=>`<div class="stat-line"><span>${esc(s.difficulty)}</span><b>${s.correct}/${s.total}</b></div>`).join('')||'<p class="small muted">풀이 전에 난이도가 저장된 원문 기록이 없습니다. 원인 상세 기록에서 체감 난이도를 남길 수 있습니다.</p>'}<p class="small muted">반복 시도를 포함한 재풀이 결과이며 최초 시험 정답률과 다릅니다.</p></details>`;
return `<h1>무엇이 나아졌는지 확인하기</h1><div class="subnav">${[['weakness','실수 변화'],['tests','최초 시험 성적'],['week','최근 7일'],['plan','14일 훈련']].map(([key,t])=>`<button data-growth-tab="${key}" class="${growthTab===key?'active':''}">${t}</button>`).join('')}</div>${content}`;}
function testView(){return `<p class="muted">원보고서에서 확인된 분모만 사용합니다. 재풀이 성적과 분리합니다.</p>${B.tests.map(t=>{const note=P.state.testNotes[t.id]||{},reading=t.scores.filter(s=>s.section==='Reading'),listening=t.scores.filter(s=>s.section==='Listening');const sum=rows=>rows.reduce((o,r)=>({correct:o.correct+r.correct,total:o.total+r.total}),{correct:0,total:0}),R=sum(reading),L=sum(listening);return `<section class="card"><h2>${t.id} · ${t.date}</h2><p>읽기 <b>${R.correct}/${R.total} (${(R.correct/R.total*100).toFixed(1)}%)</b> · 듣기 ${t.partialListening?'<b>전체 정확도 산출 불가</b> · 확인 미니세트만 '+L.correct+'/'+L.total:`<b>${L.correct}/${L.total} (${(L.correct/L.total*100).toFixed(1)}%)</b>`}</p>${t.partialListening?'<div class="warning">추가 단독 오답 6개의 전체 문제 수가 없습니다. 9/13을 전체 Listening 정확도로 확대하지 않습니다.</div>':''}<div class="table-wrap"><table class="history-table"><thead><tr><th>영역·유형</th><th>정답/전체</th><th>정답률</th></tr></thead><tbody>${t.scores.map(s=>`<tr><td>${s.section} · ${esc(s.type)}</td><td>${s.correct}/${s.total}</td><td>${(s.correct/s.total*100).toFixed(1)}%</td></tr>`).join('')}</tbody></table></div><details><summary>시험 환경·시간·체감 난이도 남기기</summary><form data-test-note="${t.id}"><p class="small muted">기록이 없는 값은 빈칸입니다. 뒤늦게 입력하는 사용자 회고로 원보고서와 구분됩니다.</p><div class="form-grid"><label>소요 시간 (분)<input type="number" min="0" name="timeSpent" value="${esc(note.timeSpent??'')}"></label><label>제한 시간 (분)<input type="number" min="0" name="timeLimit" value="${esc(note.timeLimit??'')}"></label><label>체감 난이도<select name="difficulty"><option value="">기록 없음</option>${['쉬움','보통','어려움'].map(v=>`<option ${note.difficulty===v?'selected':''}>${v}</option>`).join('')}</select></label><label>집중도 (1–5)<input type="number" min="1" max="5" name="concentration" value="${esc(note.concentration??'')}"></label><label>시험 형식<input name="format" value="${esc(note.format||'')}"></label><label>풀이 환경<input name="environment" value="${esc(note.environment||'')}" placeholder="예: 실전 시간제한 / 시간제한 없음"></label><label>특이사항<textarea name="notes">${esc(note.notes||'')}</textarea></label></div><button>회고 기록 저장</button><p class="test-note-message" role="status"></p></form></details></section>`;}).join('')}<p class="small muted">읽기 C-Test는 13/20 → 14/20 → 16/20입니다. 시험별 문항과 난이도가 달라 이 변화만으로 같은 원인이 해결됐다고 판단하지 않습니다.</p>`;}
const planTopics=['자료와 원인 확인','대상·특징 연결','직접 정보·다음 행동','질문의 범위','빈칸의 품사·형태','발화 기능','새 문제 첫 적용','강의 전체 구조','원인·결과와 추론','문맥 어휘','시간을 확인하며 혼합 훈련','재발한 원인 다시 확인','새 문제 재확인','재발 오류와 어휘 마무리'];
function planView(){return `<p class="muted">실제 시험일이 확인되지 않아 학습 일차로 표시합니다. 완료 표시는 직접 체크하며 풀이·진단 기록과 별도로 보존합니다.</p><section class="card">${planTopics.map((topic,i)=>`<div class="list-item"><div><b>${i+1}일차 · ${topic}</b><p class="small muted">원인 확인 → 관련 원문 → 어휘 회상 → 새 문제 적용</p></div><label class="checkbox"><input type="checkbox" data-plan-day="${i+1}" ${P.state.testNotes['PLAN-'+(i+1)]?.complete?'checked':''}>완료</label></div>`).join('')}<div class="row"><button data-page="rules">교정 규칙별 훈련 고르기</button><button data-page="vocab">관련 어휘 복습</button></div></section>`;}
function history(){return historyBase()+`<h2 class="section-heading">원인과 연결된 복습 기록</h2><section class="card">${P.state.attempts.slice().reverse().slice(0,20).map(r=>`<div class="list-item"><div><b>${esc(name(r.id))}</b><p class="small muted">${date(r.time)} · 풀이 ${duration(r.timeSpentMs)} · 확신도 ${esc(r.confidence??'미기록')}<br>풀이 전 규칙: ${esc(r.analysisSnapshot?.correctionRule||'확인된 규칙 없음')}<br>이번 판단: ${esc({same:'같은 원인 재발',resolved:'규칙 적용 확인',different:'다른 원인',unknown:'확인 필요'}[r.assessment?.outcome]||'미확인')}<br>판단 근거: ${esc(r.assessment?.evidence||'미기록')}</p></div><button data-analyze="${r.id}">현재 진단 보기</button></div>`).join('')||'<p class="muted">풀이를 하면 문제와 교정 규칙의 연결이 여기에 기록됩니다.</p>'}</section><p class="small muted">백업에는 문제 진단·교정 규칙의 변경 이력·어휘 복습·시험 회고·14일 체크까지 함께 포함됩니다.</p>`;}
function bindLearning(){app.querySelectorAll('[data-page="vocab"]').forEach(b=>b.onclick=()=>{vocabId=null;navigate('vocab')});const on=(selector,event,fn)=>document.querySelector(selector)?.addEventListener(event,fn);
 app.querySelectorAll('[data-analyze]').forEach(b=>b.onclick=()=>startAnalysis(b.dataset.analyze));app.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{vocabId=b.dataset.word;wordRevealed=false;wordAnswer='';navigate('vocab')});
 app.querySelectorAll('[data-growth-tab]').forEach(b=>b.onclick=()=>{growthTab=b.dataset.growthTab;render()});
 app.querySelectorAll('[data-rule-train]').forEach(b=>b.onclick=()=>{const candidates=T.filter(q=>q.ruleId===b.dataset.ruleTrain||q.targetCode===spec().rules.find(r=>r.id===b.dataset.ruleTrain)?.code);const q=candidates.find(q=>!P.latest(q.id))||candidates[0];if(q)open(q.id,true);else{courseFilter='transfer';navigate('courses')}});
 on('#confidence','change',e=>{draft.confidence=e.target.value?Number(e.target.value):null;saveDraft()});on('#predicted-pos','change',e=>{draft.predictedPOS=e.target.value;saveDraft()});
 on('#analysis-form','input',e=>{if(page==='practice'){const form=e.currentTarget,data=Object.fromEntries(new FormData(form));data.secondary=(data.secondaryText||'').split(/[,/\s]+/).filter(Boolean);draft.analysisForm=data;saveDraft()}});
 on('#primary-code','change',e=>{const rule=B.rules.find(r=>r.code===e.target.value);document.querySelector('#correction-rule').value=rule?.text||'';if(page==='practice'){const f=Object.fromEntries(new FormData(document.querySelector('#analysis-form')));f.secondary=(f.secondaryText||'').split(/[,/\s]+/).filter(Boolean);draft.analysisForm=f;saveDraft()}});
 on('#analysis-form','submit',e=>{e.preventDefault();const f=e.currentTarget,data=Object.fromEntries(new FormData(f)),qid=f.dataset.qid;try{data.secondary=[...new Set((data.secondaryText||'').split(/[,/\s]+/).filter(x=>x&&x!==data.primary))];if(data.secondary.some(c=>!B.taxonomy.some(t=>t.code===c)))throw Error('추가 원인에는 가이드의 세부 코드(예: V5, G9, LI5)를 입력해주세요.');const rule=B.rules.find(r=>r.code===data.primary);data.ruleId=rule?.id||'RULE-USER-'+qid+'-'+data.primary;data.evidenceSpan=data.evidenceSpan||'';P.saveAnalysis(qid,data);const badge=f.closest('.analysis-panel').querySelector('.badge');badge.textContent=data.primary==='unknown'?'사용자 기록 · 원인 미확정':'내가 확인한 진단';badge.className='badge good';if(page==='practice'){delete draft.analysisForm;saveDraft();}document.querySelector('#analysis-message').textContent='내가 확인한 원인·교정 규칙으로 저장했습니다. 이후 풀이부터 이 규칙을 기준으로 비교합니다.';}catch(err){document.querySelector('#analysis-message').textContent=err.message;}});
 on('#save-assessment','click',()=>{const qid=page==='practice'?id:analysisId,r=P.latest(qid);try{P.assessAttempt(r.uid,{outcome:document.querySelector('#assessment-outcome').value,evidence:document.querySelector('#assessment-evidence').value});document.querySelector('#assessment-message').textContent='이번 복습 결과를 저장했습니다. 변화 확인에서 집계 기준과 함께 볼 수 있어요.';}catch(err){document.querySelector('#assessment-message').textContent=err.message;}});
 if(document.querySelector('#assessment-outcome'))document.querySelector('#assessment-outcome').value=P.latest(page==='practice'?id:analysisId)?.assessment?.outcome||'unknown';
 on('#vocab-search','input',e=>{vocabSearch=e.target.value;const pos=e.target.selectionStart;render();const input=document.querySelector('#vocab-search');input.focus();input.setSelectionRange(pos,pos)});on('#vocab-filter','change',e=>{vocabMode=e.target.value;render()});if(document.querySelector('#vocab-filter'))document.querySelector('#vocab-filter').value=vocabMode;
 on('#word-list','click',()=>{vocabId=null;wordRevealed=false;navigate('vocab')});on('#word-answer','input',e=>wordAnswer=e.target.value);on('#reveal-word','click',()=>{wordRevealed=true;render()});
 app.querySelectorAll('[data-word-result]').forEach(b=>b.onclick=()=>{P.reviewVocab(vocabId,{result:b.dataset.wordResult,answer:wordAnswer,revealed:true});document.querySelector('#word-message').textContent='어휘 복습 결과를 저장했습니다. 연결 문제에서 다시 적용해 보세요.';});
 on('#word-edit','submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));try{data.questionIds=[...new Set((data.questionIdsText||'').split(/[,\s]+/).filter(Boolean))];if(data.questionIds.some(qid=>!Q[qid]))throw Error('존재하는 문항 ID를 입력해주세요. 예: TPO4-R1');data.meaning=data.contextMeaning;data.linkStatus='confirmed';P.saveVocab(vocabId,data);wordRevealed=false;render();document.querySelector('#word-message').textContent='어휘 내용·내 학습 상태·문제 연결을 확인해 저장했습니다.';}catch(err){document.querySelector('#word-edit-message').textContent=err.message;}});
 on('#new-word','click',()=>{const vid='VOC-USER-'+Date.now();P.state.customVocab[vid]={id:vid,term:'새 단어',meaning:'',questionIds:[],learnerStatus:'unconfirmed',sources:[{test:'사용자 추가',source:'직접 입력'}],updatedAt:new Date().toISOString()};P.persist();vocabId=vid;wordRevealed=false;wordAnswer='';navigate('vocab')});
 app.querySelectorAll('[data-test-note]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(f));P.saveTest(f.dataset.testNote,data);f.querySelector('.test-note-message').textContent='사용자 회고 기록으로 저장했습니다.';});app.querySelectorAll('[data-plan-day]').forEach(c=>c.onchange=()=>P.saveTest('PLAN-'+c.dataset.planDay,{complete:c.checked}));
}
setInterval(()=>{if(id&&page==='practice'&&!draft.checked){tick();const el=document.querySelector('#practice-time');if(el)el.textContent='풀이 시간 '+duration(draft.timeSpentMs||0)+' · 화면을 떠난 시간 제외';}},1000);
document.addEventListener('visibilitychange',()=>{tick(true);saveDraft();});

document.querySelectorAll('.tabs [data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));window.addEventListener('pagehide',saveDraft);window.addEventListener('storage',()=>{P.reload();if(page!=='practice')render()});window.addEventListener('hashchange',route);
function route(){const path=location.hash.slice(1).split('/');if(path[0]==='question'&&Q[path[1]])open(path[1]);else if(path[0]==='analysis'&&Q[path[1]]){analysisId=path[1];navigate('analysis',false);}else if(path[0]==='vocab'&&path[1]){vocabId=path[1];navigate('vocab',false);}else navigate(['home','courses','bank','history','review','analysis','vocab','rules','growth'].includes(path[0])?path[0]:'home',false);}route();
})();
